"""달성군을 본뜬 5년치(2021년 제2기 ~ 2026년 제1기) 지난 신고서 글자 — 값은 지어냄, 등록번호는 시험용(555-83-0000x).
심은 오류(수용 시험 F1~F4 가 식으로 견줌):
  2022-1 확정  공통매입세액 안분 — 총공급가액에 과세 매출이 빠짐(50M → 80M)        확정 300,000
  2022-2       신고서 없음(빠진 과세기간)
  2023-1 확정  같은 기간 두 장(뒤 파일 = 수정신고)
  2023-2 확정  정산 내역 ⑲ 가산 불공제 220,000(바른 값 120,000)                   확정 100,000
  2024-1       예정 안분(40%) 뒤 확정에서 6개월 비율(25%)로 정산하지 않음, 사업장 2곳  확정  60,000
  2024-2 확정  ⑤ 면세사업등 관련 불공제 2,000,000                                최대 2,000,000
  2025-1 확정  과세표준 명세 '주차장 운영업' 30,000,000(직영이면 면세)              최대 3,000,000
  2025-2 확정  면세비율 50% → 30%, 재계산 내역 없음                                 확인(공제 늘어나는 쪽)
2025-07-04 전에 낸 신고서(2025년 제1기 예정까지)는 옛 서식 칸 번호((15)합계·(16)불공제·(17)차감계).
다시 만들기: python3 scripts/fixtures/hometax/make_dalseong5y.py"""
from pathlib import Path
OUT = Path(__file__).parent / 'dalseong5y'
W = lambda n: f'{n:,}'
END = {1: (3, 31), 2: (9, 30)}
def doc(y, h, kind, reg, sales, buy, nd_txt='', nd_tax=0, base=None, old=False):
    m1, m2, d2 = (1 if h == 1 else 7), (3 if kind == '예정' and h == 1 else 9 if kind == '예정' else 6 if h == 1 else 12), (31 if (h == 1 and kind == '예정') or (h == 2 and kind == '확정') else 30)
    if kind == '확정': m1 = 1 if h == 1 else 7
    t = buy // 10; L = [f"일반과세자 부가가치세 [{'V' if kind == '예정' else ' '}]예정 [{'V' if kind == '확정' else ' '}]확정 신고서",
        f"신고기간 {y} 년 제 {h} 기 ( {m1} 월 1 일 ~ {m2} 월 {d2} 일)", f"상호(법인명) ○○군 사업자등록번호 {reg}",
        f"과세 세금계산서 발급분 (1) {W(sales)} 10/100 {W(sales // 10)}", f"매입 세금계산서 일반매입 (10) {W(buy)} {W(t)}"]
    if old: L += [f"합계 (10)-(10-1)+(11)+(12)+(13)+(14) (15) {W(buy)} {W(t)}", f"공제받지 못할 매입세액 (16) {W(nd_tax * 10)} {W(nd_tax)}", f"차감계 (15)-(16) (17) {W(buy - nd_tax * 10)} {W(t - nd_tax)}", "그 밖의 경감ㆍ공제세액 (18) 0"]
    else: L += ["고정자산매입 (12) 0 0", f"합계 (10)-(11)+(12)+(13)+(14)+(15) (16) {W(buy)} {W(t)}", f"공제받지 못할 매입세액 (17) {W(nd_tax * 10)} {W(nd_tax)}", f"차감계 (16)-(17) (18) {W(buy - nd_tax * 10)} {W(t - nd_tax)}"]
    if base: L += ["과세표준 명세"] + [f"({28 + i}) {lb} {code} {W(a)}" for i, (lb, code, a) in enumerate(base)] + [f"(32) 합계 {W(sum(a for _, _, a in base))}"]
    if nd_txt: L += ["공제받지 못할 매입세액 명세서", f"{y} 년 제 {h} 기 ( {m1} 월 1 일 ~ {m2} 월 {d2} 일)", nd_txt.strip()]
    return '\n'.join(L) + '\n'
def common(tax, total, exempt, nd): return f"3. 공통매입세액 안분 계산 명세\n1 {W(tax * 10)} {W(tax)} {W(total)} {W(exempt)} {W(nd)}\n합계 {W(tax * 10)} {W(tax)} {W(total)} {W(exempt)} {W(nd)}\n"
R1, R2 = '555-83-00001', '555-83-00002'
F = {}
F['2021_2.txt'] = doc(2021, 2, '예정', R1, 20_000_000, 10_000_000, old=True) + '\n\f\n' + doc(2021, 2, '확정', R1, 22_000_000, 12_000_000, old=True)
F['2022_1.txt'] = doc(2022, 1, '예정', R1, 20_000_000, 10_000_000, old=True) + '\n\f\n' + doc(2022, 1, '확정', R1, 40_000_000, 30_000_000, '⑨ 합계 0 0 0\n' + common(1_000_000, 50_000_000, 40_000_000, 800_000), 800_000, old=True)
F['2023_1.txt'] = doc(2023, 1, '예정', R1, 20_000_000, 10_000_000, old=True) + '\n\f\n' + doc(2023, 1, '확정', R1, 20_000_000, 10_000_000, '① 필요적 기재사항 누락 등 1 3,000,000 300,000\n⑨ 합계 1 3,000,000 300,000\n', 300_000, old=True)
F['2023_1_rev.txt'] = doc(2023, 1, '확정', R1, 20_000_000, 10_000_000, '① 필요적 기재사항 누락 등 1 2,000,000 200,000\n⑨ 합계 1 2,000,000 200,000\n', 200_000, old=True)
F['2023_2.txt'] = doc(2023, 2, '예정', R1, 21_000_000, 10_000_000, '⑨ 합계 0 0 0\n' + common(600_000, 30_000_000, 9_000_000, 180_000), 180_000, old=True) + '\n\f\n' + doc(2023, 2, '확정', R1, 21_000_000, 10_000_000, '⑨ 합계 0 0 0\n4. 공통매입세액의 정산 명세\n합계 1,200,000 25.00 300,000 180,000 220,000\n', 220_000, old=True)
F['2024_1.txt'] = doc(2024, 1, '예정', R1, 12_000_000, 10_000_000, '⑨ 합계 0 0 0\n' + common(600_000, 20_000_000, 8_000_000, 240_000), 240_000, old=True) + '\n\f\n' + doc(2024, 1, '확정', R2, 5_000_000, 2_000_000, old=True) + '\n\f\n' + doc(2024, 1, '확정', R1, 18_000_000, 10_000_000, '⑨ 합계 0 0 0\n' + common(200_000, 20_000_000, 2_000_000, 20_000), 20_000, old=True)
F['2024_2.txt'] = doc(2024, 2, '예정', R1, 20_000_000, 10_000_000, old=True) + '\n\f\n' + doc(2024, 2, '확정', R1, 20_000_000, 40_000_000, '⑤ 면세사업등 관련 10 20,000,000 2,000,000\n⑨ 합계 10 20,000,000 2,000,000\n', 2_000_000, old=True)
F['2025_1.txt'] = doc(2025, 1, '예정', R1, 20_000_000, 10_000_000, old=True) + '\n\f\n' + doc(2025, 1, '확정', R1, 50_000_000, 10_000_000, '⑨ 합계 0 0 0\n' + common(300_000, 100_000_000, 50_000_000, 150_000), 150_000, base=[('부동산업 임대', '701201', 20_000_000), ('주차장 운영업', '630201', 30_000_000)])
F['2025_2.txt'] = doc(2025, 2, '예정', R1, 20_000_000, 10_000_000) + '\n\f\n' + doc(2025, 2, '확정', R1, 35_000_000, 10_000_000, '⑨ 합계 0 0 0\n' + common(300_000, 50_000_000, 15_000_000, 90_000), 90_000)
F['2026_1.txt'] = doc(2026, 1, '예정', R1, 20_000_000, 10_000_000) + '\n\f\n' + doc(2026, 1, '확정', R1, 20_000_000, 10_000_000)
OUT.mkdir(exist_ok=True)
for n, t in F.items(): (OUT / n).write_text(t, encoding='utf-8')
print(len(F), 'files')
